ARTICLES_MORE = [
dict(id='institutions',n='10',eyebrow='家庭 · 教会 · 学校',title='彼此配合，不能彼此取代',lead='责任可以得到帮助，却不能因委托而消失；权柄应当受约束，也不能以属灵名义无限扩大。',body='''
<p>原书强调父母与教会不应放弃教养责任，反对把信仰当作普通教育之外的零碎附加。这一关切值得保留。进一步落实时，要分清<b>圣经命令的责任</b>与<b>为承担责任而作的制度选择</b>。<a class="ref" href="#source-family">作者论述</a></p>
<div class="tablewrap"><table><thead><tr><th>主体</th><th>不可推卸的工作</th><th>可以委托与合作</th><th>不应越过的界限</th></tr></thead><tbody>
<tr><td>家庭</td><td>日常教养、榜样、关怀、生活纪律；倾听孩子。</td><td>学科教学、艺术训练、学习困难支持。</td><td>不把孩子当作个人荣耀工程；不能用“顺服”取消孩子陈述事实和求助的机会。</td></tr>
<tr><td>教会</td><td>传道、圣礼、牧养、要理教导、群体关怀。</td><td>支持教师，帮助困难家庭，提供神学教导。</td><td>不能把校规一概提升为教会纪律，也不能把入读某学校作为得救或忠诚的证明。</td></tr>
<tr><td>学校</td><td>课程、教学、评价、师资管理、学生照护。</td><td>与家长沟通，与教会保持明晰的合作关系。</td><td>不能以校长权威替代家长责任或牧者职分；神学用语不能遮蔽教学不足。</td></tr>
</tbody></table></div>
<h3>欧陆改革宗视角：认信相同，不等于治理形式相同</h3><p>家长协会、董事会与教会参与办学，可以有不同组合。重点不是先给组织贴上“最属灵”的标签，而是查明：谁任命校长？谁审核课程？谁批准预算？谁处理投诉？当牧者、董事与家长发生角色冲突，谁能独立查明事实？这些答案必须写清楚，不能只靠熟人信任。</p>
<p>原书加尔文篇将办学与共同体关怀相连，特别关切教育不应成为少数富裕家庭的特权。<a class="ref" href="#source-calvin">作者论述</a> 本导读据此追问：学费政策是否真实可负担？教师是否靠长期耗尽自己维持学校？学习较慢的孩子是否仍被尊重？这些比宣传页上的“精英”更能显出教育的目的。</p>
<div class="callout gold"><b>判断权威的一个办法</b><p>权威是否能够说明理由、承认错误、接受监督，并保护弱小者？需要纪律，不等于可以羞辱；尊重儿童，也不等于放弃引导。</p></div>
'''),
dict(id='culture',n='11',eyebrow='地域文化 · 汉语课堂',title='学习西方资源，不等于把中国孩子变成文化旁观者',lead='基督的主权跨越文化；任何文化都不是无罪的，也没有哪一种语言天然比另一种更能使人得救。',body='''
<p>苏炳森的教育讨论特别面对中西、古今、信仰与文化的关系，关注语言训练及汉语处境中的实践。<a class="ref" href="#source-su">原书相关作者文章</a> <a class="ref" href="#source-language">语文教育延伸文</a> 这提示我们：翻译一套课程只是开始，理解它面对的问题、再设计适合本地学生的学习任务，才是实际工作。</p>
<div class="two"><article><h3>读中国经典</h3><p>可以欣赏文字、历史经验与道德观察，同时分辨其中关于天、人、礼、权力与救赎的前提。不能因有可取处便说它与福音完全相同，也不能因有错误便拒绝认真理解。</p></article><article><h3>读希腊罗马经典</h3><p>可以学习论证、叙事与悲剧感，同时辨认偶像崇拜、命运观、奴隶制度或精英偏见。西方古老并不等于基督教正统。</p></article></div>
<h3>“文以载道”的难点：同一个“道”，并不自动是同一位主</h3><p>中国思想中的“道”有多种语境；约翰福音1章的“道”指向与神同在、就是神、并且道成肉身的圣子。翻译用同一个汉字，可以成为交流的桥梁，却不能免去概念辨析。课堂应先解释作者在其时代说什么，再作神学比较，最后说明认同与分歧。</p>
<div class="callout"><b>一堂汉语课的原创示范</b><p>选择一段写孝亲的古文：①查字词与语境；②准确复述主张；③比较其对父母权威的理解；④与出20:12及弗6:1—4对读；⑤讨论尊重、劝谏、父母责任与神的最高权柄；⑥写一封既诚实又尊重的沟通信。不是每篇文章都强加一节经文，而是让比较真实发生。</p></div>
<h3>身体、情感与想象力不能被“重理性”挤出去</h3><p>古典阅读的果子不只是说理快。诗歌使人注意节奏与细节，故事使人进入他人的处境，音乐训练共同聆听，体育训练身体与合作。也要给学生时间停顿、悲伤、惊奇和享受创造。一个擅长辩论却不会怜悯的人，还需要继续受教。</p>
'''),
dict(id='critical',n='12',eyebrow='重点难点 · 批判性阅读',title='认真读，也认真分辨',lead='对一本教育书最忠实的回应，不是重复它最响亮的句子，而是检查它最关键的推论。',body='''
<div class="tablewrap"><table><thead><tr><th>值得保留的洞见</th><th>不能直接跳到的结论</th><th>更严谨的判断</th></tr></thead><tbody>
<tr><td>教育包含价值与目的。</td><td>所有非基督徒教师说的每个事实都是假的。</td><td>人的终极解释与具体知识需区分；可以学习真实发现，同时审视其世界观。</td></tr>
<tr><td>父母不可放弃教养。</td><td>所有基督徒必须选择同一种学校。</td><td>责任是明确的；履行方式要结合孩子需要、家庭能力、教会支持与当地处境。</td></tr>
<tr><td>经典拓展历史视野。</td><td>古老就正确，现代就错误。</td><td>时代不是可靠性的保证。新旧都要看证据、论证与伦理。</td></tr>
<tr><td>规律操练有助成长。</td><td>强度越高、服从越绝对，教育越属灵。</td><td>操练应与目标、年龄、能力相称，并留有解释、休息与申诉。</td></tr>
<tr><td>教育可以塑造习惯与文化。</td><td>优质教育必然产生重生，或保证社会复兴。</td><td>教育有真实作用，但重生出于圣灵；人无法用课程掌握历史结局。</td></tr>
<tr><td>信仰应统整学问。</td><td>每个数学步骤都必须配一节经文。</td><td>统整发生在目的、诚实、方法界限与使用方式，不靠装饰性经文贴签。</td></tr>
</tbody></table></div>
<h3>历史叙述也需要证据分层</h3><p>原书关于中国教育史、世俗化和不同宗派的叙述，含有鲜明的评价立场。读到“真正的学校已不存在”“某传统导致某后果”一类表述，要追问“真正”的定义是什么、是否有反例、因果链中是否遗漏政治和社会条件。道德确信不等于历史证据已完整。</p>
<p>关于路德与国家教育，不宜把数百年后的政治灾难简单归结为一位改教家的倡议；关于加尔文，也不宜把日内瓦描述为没有公共当局参与的纯私人学校模式。历史中的合作、冲突与制度变化，比二分标签更复杂。<a class="ref" href="#source-luther">对读路德篇</a> <a class="ref" href="#source-calvin">对读加尔文篇</a></p>
<div class="callout rose"><b>能分辨，才是真的学会</b><p>当你能够尊重一位作者、准确复述他的理由，同时指出一个仍须论证的推论，你已经在实际操练文法、逻辑和修辞。</p></div>
'''),
dict(id='practice',n='13',eyebrow='家庭与课堂 · 可执行方案',title='从一周能做到的事开始',lead='这不是原书课程表，而是依据前述原则设计的学习示范。先形成可持续节律，再增加内容。',body='''
<div class="tablewrap"><table><thead><tr><th>场景</th><th>读与听</th><th>问与辨</th><th>说与行</th></tr></thead><tbody>
<tr><td>学龄前亲子</td><td>短故事、诗歌、自然观察，每次约5—10分钟，随孩子状态调整。</td><td>“发生了什么？”“他为什么难过？”允许回答不知道。</td><td>用自己的话复述一句，练习感谢、收拾和帮助；不要正式逻辑化。</td></tr>
<tr><td>小学阶段</td><td>朗读、词句、故事顺序、基础数理与动手观察。</td><td>区分“我看见”与“我猜想”，寻找故事中的理由。</td><td>一段口述、一张图、一份观察记录；逐步学习核对。</td></tr>
<tr><td>青少年</td><td>阅读原文节选与相反观点，掌握历史背景。</td><td>检查概念、证据、前提、反例和替代解释。</td><td>写短论证，回应反对意见，完成服务性项目。</td></tr>
<tr><td>成人共读</td><td>每次一个专题，先读原书指定篇章。</td><td>分别标出原文、史实、推论和应用。</td><td>提交一页教学改进方案；下次报告实践结果。</td></tr>
</tbody></table></div>
<h3>一周示范：学习“水与邻舍”</h3><div class="week"><div><b>周一 · 观察</b><p>记录家里哪些活动用水，不急着评价。</p></div><div><b>周二 · 阅读</b><p>读一段水循环说明，解释三个关键词。</p></div><div><b>周三 · 推理</b><p>比较两种节水方案，查看证据与代价。</p></div><div><b>周四 · 表达</b><p>向家人提一个可执行的建议，并听取意见。</p></div><div><b>周五 · 反思</b><p>观察是否有用，诚实报告失败与改进。</p></div></div>
<p>神学整合不是说“多节水就更配得救”，而是：受造世界值得照顾，真实数据不能捏造，邻舍的需要值得考虑，有限的人可以承认方案不完美。对年幼儿童，只保留观察、感谢和一个小行动即可。</p>
<h3>家长可用的三句话</h3><ul><li><b>接纳身份：</b>“你考得不好，我仍然爱你；我们一起来看困难在哪里。”</li><li><b>明确责任：</b>“可以不会，但不能假装会；需要帮助时请说出来。”</li><li><b>建立盼望：</b>“错误需要处理，却不必隐藏；我们可以悔改、补救，再练习。”</li></ul>
<p>若孩子持续读写困难、注意困难或明显焦虑，不要把一切归为“缺乏顺服”。应了解其具体需要，调整教学，并寻求适合的专业评估与支持。尊重受造差异，是认真教学的一部分。</p>
'''),
dict(id='school',n='14',eyebrow='办学判断 · 从使命到制度',title='先让异象变得可问责',lead='学校的属灵词汇越丰富，越需要清楚说明它在课堂、财务和学生照护中究竟意味着什么。',body='''
<div class="flow"><div><b>使命</b><p>希望学生能认识、判断、行动什么？</p></div><div><b>课程</b><p>用哪些材料与任务达成目标？</p></div><div><b>教学</b><p>教师是否有能力示范并提供反馈？</p></div><div><b>评价</b><p>从真实作品和学生成长中检验。</p></div></div>
<div class="two"><article><h3>访校时问的六个问题</h3><ol><li>请给我看一份真实教案，而不只是教育理念。</li><li>学生不会时，你们怎样诊断和帮助？</li><li>如何教学生准确表达不同于老师的意见？</li><li>教师如何接受督导、培训和合理休息？</li><li>家长投诉由谁处理？校方是否能回避利益冲突？</li><li>评价如何兼顾知识、能力、品格与个别差异？</li></ol></article><article><h3>比宣传词更有用的证据</h3><p>看学生能否复述所读内容、解释自己的推理、指出证据来源、在错误后修改作品。看教师是否愿意展示普通学生的成长，而不只展示最优秀的样本。看学校是否说清能提供什么、目前做不到什么。</p><p>教义一致很重要，教学质量也需要单独观察；“我们认信正确”并不能自动证明每一节课教得好。</p></article></div>
<h3>九十天阅读与改进计划</h3><div class="three"><article><span class="tag">第1—30天</span><h3>统一词义</h3><p>共读目的与性质；写出对人、学习、纪律和成功的定义。收集家庭与教师的实际困难。</p></article><article><span class="tag purple">第31—60天</span><h3>小范围试教</h3><p>选择一个单元，加入准确复述、证据辨析与表达任务；保留学生作品，观察负担。</p></article><article><span class="tag orange">第61—90天</span><h3>复盘与修订</h3><p>比较学习前后表现，听取学生反馈；修改任务和沟通方式，再决定是否扩大。</p></article></div>
<p class="source-note">本节为原创实践框架，不是办学许可或法律意见。原书下篇应作为历史经验阅读；现实中的注册、师资、学生权益与学历要求须按所在地另行核实。</p>
'''),
]

QUESTIONS = [
('为什么“基督教教育”不能缩减为每天加一节圣经课？','因为教育还通过奖惩、榜样、知识解释和成功标准塑造人。如果圣经课讲恩典，其余课程却不断暗示只有高分者才值得尊重，学生接收到的是冲突信息。','检查自己最常赞扬孩子什么：只有分数，还是也看诚实、关怀和真实努力？'),
('既然教育不是价值中立，是否就不能向非基督徒学习？','不是。终极信念会影响解释与目的，却不使人的每项观察都失真。基督徒可以学习真实的语言知识、数学推理、历史资料与科学发现，同时分辨其中超出证据的哲学结论。','练习把一段文字分为可核实事实、解释框架与价值判断。'),
('圣约身份是否保证每个孩子已经重生？','不能这样推论。约的群体归属带来应许、教养与责任，不是对每个人内心状态的无误宣判。家庭和教会应真诚传福音、呼召信心与悔改，既不冷待孩子，也不制造虚假的确据。','对照海德堡74、比利时34及多特第三／四项，区分洗礼、教养与圣灵更新。'),
('三艺是否等于小学只背诵、初中才思考、高中才表达？','不是。三个动作在各阶段都有需要，只是材料难度、独立程度与训练重点不同。机械分段会压制低龄儿童的好奇，也会忽略成年初学者对基础记忆的需要。','用同一个故事分别设计一个观察题、理由题与复述题。'),
('严格纪律与福音恩典冲突吗？','不必冲突。恩典不等于没有界限；纪律也不等于羞辱和恐吓。恰当的纪律说明错误、保护他人、安排相称后果并提供恢复路径。只有惩罚没有恢复，或者只有宽容没有责任，都不完整。','回看一次冲突：有没有查明事实、解释规则、承认成人错误、安排补救？'),
('为什么不能把查理曼或君士坦丁当作基督教教育的救主？','他们的政策改变了教会和学校的公共处境，但政治支持不能代替真信心，帝国扩张也不等于神国扩展。历史意义与神学终极地位需要严格区分。','用一句话分别说出313、325、380；不要把宽容、教义会议和官方宗教混为一谈。'),
('两个“腓特烈三世”为什么总混淆？','因为编号依各自领地计算。萨克森的腓特烈智者与普法尔茨的腓特烈三世并非同一个人。前者联系维滕堡与路德，后者联系海德堡和1563年要理问答。','记人名时同时记领地、城市、事件，不能只背“腓特烈三世”。'),
('一定学拉丁文才算有基督教教育吗？','没有这样的圣经命令。拉丁文可以帮助进入西方文献传统，但学习目标、资源、母语基础与学生情况都要考虑。语言训练的价值不能变成得救、敬虔或教育优劣的单一指标。','说明你希望学某种语言是为了读什么、理解什么，而不只是获得标签。'),
('是否所有课程都必须直接从圣经推导？','圣经规范信仰、道德与人的终极目的，但它不是每门学科的技术百科。数学仍要证明，科学仍要观察实验，历史仍要考证。尊重这些方法，也是在承认受造世界具有可认识的秩序。','选一个学科任务，说明哪些判断来自经文，哪些来自观察，哪些是推论。'),
('古典教育会不会成为精英主义？','会有这种风险，尤其当经典、语言、学费和升学成绩被用来区分人的价值。应追问资源如何分配，困难学生是否得到支持，以及卓越是否用于服事。高标准与怜悯可以并存，但必须在制度中体现。','检视一个学校政策：它是否只奖励已经拥有最多资源的学生？'),
('家庭暂时无法选择理想学校，是否等于不忠心？','不能仅凭学校名称下结论。父母仍可在现有条件下持续读经、倾听、讨论、陪伴、参与教会，并与教师合作。诚实评估现实限制，逐步改善，比让家庭背负无法承担的属灵压力更有益。','先选一件本周可以持续做的小事，而不是一次改变所有安排。'),
('怎样知道读完本书真的有收获？','不是只会说三艺七艺，而是能准确复述作者、分辨证据与推论、解释不同制度的利弊，并修改一个真实的教学习惯。最后的检验包括更诚实地求知、更耐心地教导、更具体地爱邻舍。','写150字：我改变了哪个判断？依据是什么？将尝试什么？何时复盘？'),
]

